// Writes src/dsp/bench24data.ts from tests/dsp/vectors/dspcore.json: the DSP core's benchmark inputs and coefficients as
// literals, so the chapter and the sandbox example need no test file. tests/dsp-core-bench.test.ts holds the two equal.
//   node node_modules/vite-node/vite-node.mjs scripts/dsp/dspcore-data.ts
import { readFileSync, writeFileSync } from 'node:fs';

const d = JSON.parse(readFileSync('tests/dsp/vectors/dspcore.json', 'utf8'));
const arr = (a: number[]) => `[${a.join(', ')}]`;
const lines = [
  '// Generated by scripts/dsp/dspcore-data.ts from tests/dsp/vectors/dspcore.json (scripts/dsp/oracle.py): do not edit.',
  '// The DSP core benchmarks\' inputs and quantized coefficients (Q1.15 words; the biquads in Q3.13).',
  '',
  `export const FIR16_DATA = { h: ${arr(d.fir16.h)}, x: ${arr(d.fir16.x)} };`,
  `export const FIR64_DATA = { h: ${arr(d.fir64.h)}, x: ${arr(d.fir64.x)} };`,
  `export const BIQUAD_DATA = { sections: ${JSON.stringify(d.biquad.sections)} as number[][], x: ${arr(d.biquad.x)} };`,
  `export const DOT_DATA = { x: ${arr(d.dot.x)}, y: ${arr(d.dot.y)} };`,
  `export const FFT_DATA = { re: ${arr(d.fft.re)}, im: ${arr(d.fft.im)}, wr: ${arr(d.fft.wr)}, wi: ${arr(d.fft.wi)} };`,
  '',
];
writeFileSync('src/dsp/bench24data.ts', lines.join('\n'));
console.log('wrote src/dsp/bench24data.ts');
